template<typename T>
inline auto sigmoid_cheb_clamp_tanh_9(T x) -> T
{
    const auto xc = std::fmin(std::fmax(x, T(-9.0)), T(9.0));
    const auto x2 = xc * xc;
    auto r = T(3.3995583204209326e-06);
    r = r * x2 + T(0.00019360013600288898);
    r = r * x2 + T(0.008344649734827807);
    r = r * x2 + T(0.16666253693925448);
    r = r * x2 + T(1.0);
    const auto s = xc * r;
    return s / std::sqrt(s * s + T(1));
}
